style.css:
@-moz-document domain("roblox.com") {
/* Target the main 'Play' button on the game page */
    .btn-common-play-game-lg, 
    .btn-primary-md {
        /* Really Light Baby Blue color */
        background-color: #b0e0e6 !important; /* This is a very light, powder blue */
        
        /* Optional: Change the border to a slightly deeper blue */
        border-color: #87ceeb !important; 
        
        /* Ensure the text is readable (dark text on a light background) */
        color: #1f1f1f !important;
    }

    /* Target the hover state to keep the baby blue look when mousing over */
    .btn-common-play-game-lg:hover, 
    .btn-primary-md:hover {
        background-color: #87ceeb !important; /* A slightly deeper blue for the hover effect */
        border-color: #6495ed !important;
    }
}
